def transform(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    pts={}
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg: pts.setdefault(g[i][j],set()).add((i,j))
    out=[r[:] for r in g]
    def free(i,j):
        return 0<=i<h and 0<=j<w and g[i][j]==bg
    for c,p in pts.items():
        if len(p)<2: continue
        best=None
        for (di,dj) in ((1,1),(1,-1)):
            from collections import defaultdict
            lines=defaultdict(list)
            for (i,j) in p: lines[i*dj - j*di].append((i,j))
            for k,v in lines.items():
                if len(v)>=2 and (best is None or len(v)>best[0]):
                    best=(len(v),(di,dj),v)
        if best is None: continue
        _,(di,dj),v=best
        v=sorted(v)
        a,b=v[0],v[-1]
        for start,(si,sj) in ((a,(-di,-dj)),(b,(di,dj))):
            i,j=start[0]+si,start[1]+sj
            while free(i,j):
                out[i][j]=c; i+=si; j+=sj
    return out

